void ScriptSession::cancelWork(UnitState& u) {
    u.buildOrder.reset();u.repair.reset();u.entangleTarget=u.entangleType=0;if(u.animation=="Stand Work"){u.animation.clear();u.animationTime=0;}if(!u.workingOn)return;
    if(u.workingInside && alive(u.workingOn,NativeKind::Unit))if(auto point=spawnPoint(*units_.at(u.workingOn),u.type)){u.x=point->x;u.y=point->y;}
    u.workingOn=0;u.workingInside=false;if(u.animation=="Stand Work"){u.animation.clear();u.animationTime=0;}++fogRevision_;
}
